 private void startSearch(){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);query.clearFocus();String q=query.getText().toString().trim();search.setEnabled(false);message("Searching YouTube…");page="search";showResults(queue);worker.execute(()->{try{List<Track> found=MusicRepository.search(this,q);runOnUiThread(()->{if(isDestroyed())return;queue=found;if("search".equals(page)){showResults(found);NativeMotion.reveal(results);}if("search".equals(page))message(found.isEmpty()?"No results. Try another search.":found.size()+" results · preview or download");});}catch(Exception e){runOnUiThread(()->message("Search failed. "+DownloadErrors.friendly(e.getMessage())));}finally{runOnUiThread(()->search.setEnabled(true));}});}
 private void navigate(String destination){
  page=destination;hideKeyboard();message("");
  if("home".equals(page))showHome();else if("library".equals(page))showLibrary();else showResults(queue);
  scroll.scrollTo(0,0);NativeMotion.reveal(results);
 }
 private void selectTab(boolean ignored){
  if(homeTab==null)return;
  Button[] buttons={homeTab,searchTab,libraryTab};String[] names={"home","search","library"};
  for(int i=0;i<buttons.length;i++){boolean selected=names[i].equals(page);buttons[i].setSelected(selected);buttons[i].setAlpha(selected?1:.65f);buttons[i].setBackground(selected?GlassTheme.panel(this,22,true):new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));}
 }
 private void message(String value){status.setText(value);status.setVisibility(value.isEmpty()?View.GONE:View.VISIBLE);}
